// walk() replicated VERBATIM from recipeGuards.test.ts lines 53-63
type Found = { recipe: string; path: string; prop: string; value: string };

const walkCurrent = (node: unknown, recipe: string, path: string, hit: (f: Found) => void): void => {
  if (node === null || typeof node !== 'object') return;
  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${key}` : key;
    if (value !== null && typeof value === 'object') {
      walkCurrent(value, recipe, here, hit);
    } else if (typeof value === 'string') {
      hit({ recipe, path, prop: key, value });
    }
  }
};

// PROPOSED FIX: carry the last non-index key forward as `prop`.
const isIndex = (k: string) => /^\d+$/.test(k);
const walkFixed = (
  node: unknown, recipe: string, path: string, hit: (f: Found) => void, prop = '',
): void => {
  if (node === null || typeof node !== 'object') return;
  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${key}` : key;
    if (value !== null && typeof value === 'object') {
      // Array indices and responsive-object keys are not property names — keep the
      // enclosing property as the reported `prop`.
      const isResponsiveStep = Array.isArray(node) || isIndex(key);
      walkFixed(value, recipe, here, hit, isResponsiveStep ? prop : key);
    } else if (typeof value === 'string') {
      const inResponsiveObject = Array.isArray(node) || isIndex(key);
      hit({ recipe, path, prop: inResponsiveObject && prop ? prop : key, value });
    }
  }
};

const SPACING_KEYS = ['3xs','2xs','xs','s','m','l','xl','2xl','3xl','4xl','5xl','6xl','7xl'];
const SIZING_PROPS = new Set(['width','height','minWidth','maxWidth','minHeight','maxHeight','boxSize','w','h','minW','maxW','minH','maxH']);

const detect = (walker: typeof walkCurrent, obj: unknown) => {
  const out: Found[] = [];
  walker(obj, 'R', '', (f) => out.push(f));
  return out.filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value));
};

const CASES: Array<[string, unknown, boolean]> = [
  ['A. width: "xl"                   (should CATCH)', { width: 'xl' }, true],
  ['B. _hover: {boxSize: "2xs"}      (should CATCH)', { _hover: { boxSize: '2xs' } }, true],
  ['C. width: ["xl","2xl"]           (should CATCH)', { width: ['xl', '2xl'] }, true],
  ['D. width: {base: "xl"}           (should CATCH)', { width: { base: 'xl' } }, true],
  // false-positive controls — must NOT be flagged
  ['E. _focusVisible nested legit    (must NOT flag)', { _focusVisible: { outline: 'm solid', outlineColor: 'text.inverse' } }, false],
  ['F. transition array non-scale    (must NOT flag)', { transition: ['opacity 200ms', 'transform 200ms'] }, false],
  ['G. fontFamily array w/ scale-ish (must NOT flag)', { fontFamily: ['Futura Round', 'sans-serif'] }, false],
  ['H. padding responsive (space ok) (must NOT flag)', { padding: { base: 'xs', md: 'xl' } }, false],
  ['I. width responsive w/ units     (must NOT flag)', { width: ['100%', '50%'] }, false],
  ['J. gridTemplateAreas array       (must NOT flag)', { gridTemplateAreas: ['"a b"', '"a a"'] }, false],
  ['K. nested media query + responsive width (should CATCH)', { '@media (min-width: 48em)': { width: { base: 'xl' } } }, true],
  ['L. real footer-ish: maxWidth var (must NOT flag)', { maxWidth: 'var(--zimm-scale-7xl)' }, false],
];

for (const label of ['CURRENT walk()', 'PROPOSED walkFixed()']) {
  const walker = label.startsWith('CURRENT') ? walkCurrent : walkFixed;
  console.log(`\n===== ${label} =====`);
  let wrong = 0;
  for (const [name, obj, shouldFlag] of CASES) {
    const hits = detect(walker, obj);
    const flagged = hits.length > 0;
    const ok = flagged === shouldFlag;
    if (!ok) wrong++;
    console.log(
      `${ok ? 'ok  ' : 'WRONG'} ${name} -> ${flagged ? 'FLAGGED' : 'missed '}` +
      (hits.length ? `  ${JSON.stringify(hits.map((h) => `${h.path||'.'}|prop=${h.prop}|${h.value}`))}` : ''),
    );
  }
  console.log(`--> ${wrong} incorrect of ${CASES.length}`);
}
EOF
