  if (Array.isArray(node)) return true;
  const keys = Object.keys(node);
  return keys.length > 0 && keys.every((k) => BREAKPOINT_KEYS.has(k));
};
const walkResp = (node: unknown, recipe: string, path: string, hit: (f: Found) => void, prop = ''): void => {
