      if (isResponsiveContainer(node as object)) respShapes.push(`${recipe}.${path} => ${JSON.stringify(node)}`);
      for (const [k, v] of Object.entries(node as Record<string, unknown>)) scan(v, recipe, path ? `${path}.${k}` : k);
