import { Box, ChakraProvider } from '@chakra-ui/react';
import theme from '../index';
import * as React from 'react';

const emit = (label: string, style: Record<string, unknown>) => {
  const { container } = render(
    <ChakraProvider theme={theme}>
      <Box data-testid="t" {...style} />
    </ChakraProvider>,
  );
  const el = container.querySelector('[data-testid="t"]') as HTMLElement;
  const cs = getComputedStyle(el);
  // Emotion class -> find the rule text actually injected
  const cls = el.className.split(/\s+/).filter(Boolean);
  let ruleText = '';
  for (const sheet of Array.from(document.styleSheets)) {
    try {
      for (const rule of Array.from(sheet.cssRules)) {
        const t = (rule as CSSRule).cssText;
        if (cls.some((c) => t.includes('.' + c))) ruleText += t + ' ';
      }
    } catch { /* cross-origin */ }
  }
  console.log(
    label.padEnd(34),
    '| emitted CSS:', (ruleText.match(/\{[^}]*\}/)?.[0] ?? '(none)').padEnd(46),
    '| computed font-size=', cs.fontSize || '(empty)',
    'line-height=', cs.lineHeight || '(empty)',
