    for (const s of [resolveBaseStyle(r), r.variants, r.sizes]) walk(s, name, '', (f) => found.push(f));
  }
  return found;
};
const typographyOffenders = (map: Record<string, unknown>) =>
  collectFrom(map)
    .filter((f) => TYPOGRAPHY_PROPS[f.prop]?.includes(f.value))
    .map((f) => `${f.recipe}.${f.path || 'baseStyle'}.${f.prop}: '${f.value}'`);

describe('S4c proposed typography guard', () => {
  test('REAL theme: zero false positives', () => {
    const o = typographyOffenders(components as unknown as Record<string, unknown>);
    console.log('real-theme typography offenders:', JSON.stringify(o));
    expect(o).toEqual([]);
  });

  test('SYNTHETIC violations are all caught', () => {
    const synthetic = {
      Bad: {
        baseStyle: {
          a: { fontSize: '2xs' },                       // collision -> 10px not 14px
          b: { fontSize: '4xs' },                       // absent  -> dropped
          c: { lineHeight: '2xs' },                     // absent  -> dropped
          d: { letterSpacing: 'footer' },               // absent  -> dropped
          e: { fontSize: 'l' },                         // absent (header:302 shape)
          f: { _hover: { fontSize: '3xs' } },           // nested pseudo
          g: { fontSize: ['2xs', 'md'] },               // responsive array
          h: { fontSize: { base: '2xs', md: 'md' } },   // responsive object
          i: { '@media (min-width: 48em)': { lineHeight: { base: 'md' } } }, // media + responsive
        },
      },
    };
    const o = typographyOffenders(synthetic);
    console.log('synthetic offenders (' + o.length + '):');
    for (const x of o) console.log('   ', x);
    expect(o.length).toBe(11); // a,b,c,d,e,f,g(x2),h(x2),i
  });

  test('SYNTHETIC legitimate typography is NOT flagged', () => {
    const good = {
      Good: {
        baseStyle: {
          a: { fontSize: 'var(--zimm-font-size-2xs)' },
          b: { lineHeight: 'var(--zimm-font-lineheight-2xs)' },
          c: { letterSpacing: 'var(--zimm-font-letterspacing-footer)' },
          d: { lineHeight: 'normal' },
          e: { fontSize: '0.875rem' },
          f: { letterSpacing: '0.025rem' },
          g: { textStyle: 'body2' },
          h: { fontSize: 'inherit' },
          i: { lineHeight: '1.2' },
        },
      },
    };
    const o = typographyOffenders(good);
    console.log('legit-flagged (should be empty):', JSON.stringify(o));
    expect(o).toEqual([]);
  });
});
